+
+	private async importEntry(
+		entry: PluginEntry,
+		fingerprint: string,
+		exportName: string | undefined,
+	): Promise<void> {
+		entry.generation += 1;
+		const generation = entry.generation;
+		entry.fingerprint = fingerprint;
+		entry.extension = undefined;
+		entry.spare = undefined;
+		entry.blocked = false;
+		entry.consecutiveFailures = 0;
