+		const startedAt = Date.now();
+		try {
+			const extension = await runWithTimeout(
+				() =>
+					loadAgentPluginFromPath(entry.pluginPath, {
+						exportName,
+						freshModule: true,
+					}),
+				this.importTimeoutMs,
+				`Plugin import of ${entry.pluginPath}`,
+			);
